  ('marketdata', 'marketdata.fmp.base_url', 'exact', 'string', 'https://financialmodelingprep.com', 'FMP API base URL; endpoint paths are built under it', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/cmd/server/main.go:newFMPClient', false),
  ('marketdata', 'marketdata.fmp.cache_ttl_hours', 'exact', 'int', '24', 'Hours a cached fundamentals row stays fresh before a re-fetch is attempted', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:GetFundamentalsMulti; services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveFundamentals', false),
  ('marketdata', 'marketdata.fmp.daily_request_cap', 'exact', 'int', '250', 'Max FMP requests per UTC day (free Basic plan budget)', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/cmd/server/main.go:newFMPClient; services/xstockstrat-marketdata/internal/service/marketdata_service.go:fundamentalsQuota', false),
  ('marketdata', 'marketdata.fmp.enabled', 'exact', 'bool', 'false', 'Master gate for the FMP fundamentals source; off by default', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/etf_flags.go:etfFillGate; services/xstockstrat-marketdata/internal/service/marketdata_service.go:fundamentalsEnabled', false),
  ('marketdata', 'marketdata.fmp.metrics', 'exact', 'string', 'core,extended', 'Comma-separated metric tiers to fetch (core, extended)', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/cmd/server/main.go:newFMPClient', false),
  ('marketdata', 'marketdata.fmp.rate_limit_rps', 'exact', 'int', '5', 'FMP token-bucket ceiling (burst = 1; feature 217). 5 rps = FMP Starter''s 300/min. `0` = unthrottled. Read live per call.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/cmd/server/main.go:newFMPClient', false),
  ('marketdata', 'marketdata.fundamentals.history.backfill.max_lookback_years', 'exact', 'int', '10', 'Default lookback (years) when a `BackfillFundamentals` request omits a range start.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:BackfillFundamentals', false),
  ('marketdata', 'marketdata.fundamentals.history.backfill.period_types', 'exact', 'string', 'both', 'Default period types to backfill (`quarterly`\|`annual`\|`both`) when the request omits them.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:BackfillFundamentals', false),
  ('marketdata', 'marketdata.fundamentals.history.enabled', 'exact', 'bool', 'false', 'Master gate for the historical point-in-time fundamentals **backfill** (feature 198). Read on `BackfillFundamentals`; the as-of read (`GetHistoricalFundamentals`) is not gated (a stored filing is already public).', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:BackfillFundamentals', false),
  ('marketdata', 'marketdata.fundamentals.history.ratio_enrichment.enabled', 'exact', 'bool', 'false', 'Gate for the optional FMP ratio-fill pass. **Gated on the shared FMP day budget (`marketdata.fmp.daily_request_cap`, feature 217)** — no second cap, no new credential (reuses the feature-147 `marketdata.fmp.api_key`). v1 wires no PIT FMP ratio source, so this is a guarded seam.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:BackfillFundamentals', false),
  ('marketdata', 'marketdata.fundamentals.provider', 'exact', 'string', 'finnhub', 'Selects the active source.FundamentalsSource: finnhub or fmp. Read once at boot -- changing it takes effect on next restart, not live, unlike the other fundamentals keys.', 'xstockstrat-marketdata', false, 'services/xstockstrat-analysis/app/engine/fundsignal_loop.py:__init__; services/xstockstrat-marketdata/cmd/server/main.go:main', true),
  ('marketdata', 'marketdata.fundamentals.snapshot_source', 'exact', 'string', 'vendor', 'Live-read serving source for the latest-fundamentals snapshot RPCs (feature 211): "edgar" derives the snapshot from the latest as-reported SEC filing + a live price; "vendor" is the FMP/Finnhub path. Seeded vendor (no serving change at deploy); the live-flip to edgar is the rollout. Unrecognized value → WARN + fail-safe to vendor.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:snapshotSource', false),
  ('marketdata', 'marketdata.price.batch_timeout_ms', 'exact', 'int', '2500', 'Feature 227 — budget (ms) for the shared `BatchGetLatestPrice` singleflight closure, which runs on a context **detached** from the first caller''s cancellation/deadline (`context.WithoutCancel`) so coalesced waiters are not cancelled by it; symbols not fetched within it are omitted (never fabricated) and every dropped error is logged as a WARN. Read live per call; `value_type` must be `int` (any other type reads as the default); `≤ 0` or no config watcher → `2500`. Unseeded (feature 227 seeding waiver); SetConfig-bounded `[500,2500]`.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveBatchPriceBudget', false),
  ('marketdata', 'marketdata.quotes.batch_timeout_ms', 'exact', 'int', '2500', 'Feature 229 — budget (ms) for the detached `GetLatestQuotes` cold-fetch singleflight closure (`context.WithoutCancel`, so a cancelled first caller never fails coalesced waiters). On a cold failure/timeout the call returns the warm subset, cold symbols omitted (never zero-filled), with a WARN `GetLatestQuotes: cold fetch failed`. Read live per call; `≤ 0` or no watcher → `2500`. Must stay, together with `marketdata.quotes.mark_timeout_ms` (bound = max of the two), below `portfolio.marketdata.quote_timeout_ms` minus the warm read. Unseeded; SetConfig-bounded `[500,5000]`.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveQuoteBatchBudget', false),
  ('marketdata', 'marketdata.quotes.latest_lookback_hours', 'exact', 'int', '168', 'Feature 229 — recency window (hours) of both cached quote readers (`GetLatestQuote`, `GetLatestQuotesBatch`: `time >= now − window`, so TimescaleDB excludes older chunks at plan time) and of the cache-age guard (a quote older than the window is returned but never cached). A symbol with no in-window row is cold and fetched live. 7 days covers 3-day weekends + holidays. Read live per call; `≤ 0` or no watcher → `168`. Unseeded (feature 227 D2-style waiver); SetConfig-bounded `[24,720]`.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveQuoteLookback', false),
  ('marketdata', 'marketdata.quotes.mark_close_max_age_hours', 'exact', 'int', '168', 'Feature 231 — max age (hours) of the stored `1d` close usable as a mark; an older (or absent) close leaves `mark_price` unset (never fabricated). Read live per call; `≤ 0` or no watcher → `168`. Unseeded; SetConfig-bounded `[120,720]`.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveMarkCloseMaxAge', false),
  ('marketdata', 'marketdata.quotes.mark_timeout_ms', 'exact', 'int', '500', 'Feature 231 — per-caller budget (ms) for the `GetLatestQuotes` stored-close lookup that backs `Quote.mark_price` for returned quotes lacking a positive bid and ask (a symbol with no quote at all is still omitted); it runs concurrently with the cold fetch, and on timeout/error those symbols return without `mark_price` and a WARN `GetLatestQuotes: mark lookup failed`. Read live per call; `≤ 0` or no watcher → `500`. Unseeded; SetConfig-bounded `[100,2500]`.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveQuoteMarkBudget', false),
  ('marketdata', 'marketdata.retention.quotes_days', 'exact', 'int', '90', 'Feature 229 — quote retention (days), enforced by `StartQuoteRetention` (app-level `drop_chunks`; DO''s Apache-edition TimescaleDB has no `add_retention_policy`). Read live each hourly run; `≤ 0` or no watcher → `90`, never clamped — a run is **skipped with a WARN** when `days*24 <= marketdata.quotes.latest_lookback_hours` (so it never drops rows the windowed reads serve). Unseeded; SetConfig-bounded `[31,3650]`. See § Quote retention.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:resolveQuoteRetentionDays', false),
  ('marketdata', 'marketdata.stream.bar_ingest_interval_ms', 'exact', 'int', '300000', 'Interval for the always-on bar ingester that upserts recent bars for every queried symbol into `marketdata.ohlcv`. Read live each cycle; `0`/negative pauses it. Default 5m (feature 140): with continuous **daily** ingestion, the forming daily bar needn''t refresh every 60s — the UI''s 5-min chart poll and `GetBars`'' staleness fallback additionally cover freshness.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:StartBarIngestPoller', false),
  ('marketdata', 'marketdata.stream.bar_ingest_lookback_ms', 'exact', 'int', '900000', 'Lookback window the always-on ingester re-fetches each cycle. Overlap is harmless because inserts upsert, and a window wider than the interval lets the feed self-heal after a pause/restart. This raw value (15min) is far too short for the `1d` default — but `ingestRecentBars` widens each timeframe''s own window to at least 2× that timeframe''s interval (`minIngestLookback`), so `1d` always looks back ≥48h regardless of this key''s value.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:ingestRecentBars', false),
  ('marketdata', 'marketdata.stream.bar_ingest_timeframe', 'exact', 'string', '1d', 'Bar timeframe(s) the always-on ingester fetches each cycle. A comma-separated list mechanism (not a single value), parsed by the count-agnostic `resolveIngestTimeframes` — feature 143 narrowed the *default* from `15m,1d` to `1d` (feature 140 flipped the platform to daily) because `GetBars`/`BackfillBars` now reject any non-`1d` request, so continuously ingesting 15m served no consumer. Continuous `1d` ingestion keeps daily bars fresh. Each entry is canonicalized through `internal/timeframe`; an unresolvable entry is skipped with a WARN (not a whole-list fallback), and an empty/wholly-unresolvable value falls back to the default. To pause ingestion, use `bar_ingest_interval_ms <= 0` — never a bogus timeframe value.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:ingestRecentBars', false),
  ('marketdata', 'marketdata.stream.max_reconnects', 'exact', 'int', '10', 'Max reconnect attempts before alert', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/cmd/server/main.go:main', false),
  ('marketdata', 'marketdata.stream.reconnect_delay_ms', 'exact', 'int', '2000', 'Reconnect delay on stream drop', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/cmd/server/main.go:main', false),
  ('marketdata', 'marketdata.stream.warm_interval_ms', 'exact', 'int', '30000', 'Interval for the warm-quote poller that refreshes the latest quote of every queried symbol into the DB cache. Read live each cycle; `0`/negative pauses it.', 'xstockstrat-marketdata', false, 'services/xstockstrat-marketdata/internal/service/marketdata_service.go:StartWarmQuotePoller', false),
  ('notify', 'notify.fanout.dedup_window_seconds', 'exact', 'int', '300', 'Suppress re-delivery of a byte-identical alert within this many seconds.', 'xstockstrat-notify', false, 'services/xstockstrat-notify/src/fanout/fanout.ts:dispatch', false),
  ('notify', 'notify.fanout.min_confidence_threshold', 'exact', 'float', '0.7', 'Minimum analysis readiness ordinal (fraction of passing entry-condition leaves -- NOT a probability); applied only when the alert context.conviction is present. Conviction-less alerts are gated by min_severity alone.', 'xstockstrat-notify', false, 'services/xstockstrat-notify/src/fanout/fanout.ts:dispatch', false),
  ('notify', 'notify.fanout.min_severity', 'exact', 'int', '2', 'Primary fanout gate: minimum AlertSeverity ordinal to fan out (0=UNSPECIFIED,1=INFO,2=WARNING,3=ERROR,4=CRITICAL). Clamped to [0,4] at read. Default 2 (WARNING) excludes INFO fill confirmations -- lower to 1 to fan out fills.', 'xstockstrat-notify', false, 'services/xstockstrat-notify/src/fanout/fanout.ts:dispatch', false),
  ('notify', 'notify.fanout.sendgrid_from_email', 'exact', 'string', NULL, 'Sender address for outbound fanout email. Empty until configured; email fanout stays disabled until both from/to are set AND SENDGRID_API_KEY is present.', 'xstockstrat-notify', false, 'services/xstockstrat-notify/src/fanout/fanout.ts:dispatch', false),
  ('notify', 'notify.fanout.sendgrid_to_email', 'exact', 'string', NULL, 'Recipient address for outbound fanout email. Empty until configured; email fanout stays disabled until both from/to are set AND SENDGRID_API_KEY is present.', 'xstockstrat-notify', false, 'services/xstockstrat-notify/src/fanout/fanout.ts:dispatch', false),
  ('notify', 'notify.push.min_severity', 'exact', 'int', '2', 'Web Push gate: minimum AlertSeverity ordinal to send a Web Push (0=UNSPECIFIED,1=INFO,2=WARNING,3=ERROR,4=CRITICAL). Clamped to [0,4] at read. Mirrors notify.fanout.min_severity; default 2 (WARNING) excludes INFO fill confirmations.', 'xstockstrat-notify', false, 'services/xstockstrat-notify/src/fanout/webPush.ts:dispatch', false),
  ('platform', 'platform.maintenance_mode', 'exact', 'bool', 'false', 'Halts all trading operations', 'all', false, 'services/xstockstrat-trading/internal/service/trading.go:PlaceOrder', false),
  ('platform', 'platform.trading_state', 'exact', 'string', 'HALTED', 'Richer halt state: ACTIVE | REDUCE_ONLY | HALTED. REDUCE_ONLY rejects exposure-increasing orders but permits cancellation and risk-reducing closes; HALTED rejects all exposure-increasing orders. Independent of platform.maintenance_mode.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:currentTradingState; services/xstockstrat-ui/src/app/trader/positions/page.tsx:PositionsPage', true),
  ('portfolio', 'portfolio.exposure.factor_map', 'exact', 'string', '{}', 'JSON object mapping symbol → factor name for the Exposure screen''s factor grouping (feature 083). marketdata exposes no sector, so this operator-defined map is the factor source; unmapped symbols group as "Unclassified". Read via `Watcher.FactorMap()`; invalid JSON → empty map.', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/config/config.go:FactorMap', false),
  ('portfolio', 'portfolio.marketdata.last_close_lookback_days', 'exact', 'int', '21', 'Feature 240 — how many calendar days back the offline-valuation `BatchGetBars` (`allow_partial`) searches for a daily close to mark an offline position that has no live quote (`MARK_SOURCE_LAST_CLOSE`), and the window for Day P&L''s previous close. Read live per read; nil/`≤ 0` → `21`. Unseeded (227 D2 waiver); SetConfig-bounded `[5,60]`.', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/offline_valuation.go:lastCloseLookbackDays', false),
  ('portfolio', 'portfolio.marketdata.quote_timeout_ms', 'exact', 'int', '4000', 'Feature 229 — deadline on the marketdata `GetLatestQuotes` fetch (`latestQuotesFor`, the single choke point for every read and background path). On expiry the un-broker-valued positions stay unenriched (never fabricated) and the read still answers. Must exceed max(`marketdata.quotes.batch_timeout_ms` (2500), `marketdata.quotes.mark_timeout_ms` (500)) plus the warm read so a cold timeout still returns the warm subset. Read live; nil/`≤ 0` → `4000`. Unseeded; SetConfig-bounded `[500,8000]`.', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/portfolio_service.go:quoteTimeout', false),
  ('portfolio', 'portfolio.marketdata.servability_timeout_ms', 'exact', 'int', '2000', 'Portfolio watchlist writes: deadline (ms) on the marketdata GetSymbolServability check, read live per write. A stored value <=0 reads as 2000, below 500 as 500, above 4000 as 4000. On timeout or error the write is let through with a WARN.', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/portfolio_service.go:servabilityTimeout', false),
  ('portfolio', 'portfolio.risk.concentration_limit_pct', 'exact', 'float', '0.2', 'Alert if single position > 20% of portfolio', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/portfolio_service.go:checkRiskLimits', false),
  ('portfolio', 'portfolio.risk.max_drawdown_pct', 'exact', 'float', '0.1', 'Per-account drawdown alert — a WARNING alert is emitted when an account''s peak-to-current drawdown (broker `account_balances.equity` vs persisted `peak_equity` HWM) exceeds this pct (feature 172)', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/portfolio_service.go:checkRiskLimits', false),
  ('portfolio', 'portfolio.watchlist.max_per_user', 'exact', 'int', '50', 'Max watchlists a single user may own', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/portfolio_service.go:maxWatchlistsPerUser', false),
  ('portfolio', 'portfolio.watchlist.max_symbols_per_list', 'exact', 'int', '500', 'Max symbols allowed in one watchlist', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/portfolio_service.go:maxSymbolsPerList', false),
  ('portfolio', 'portfolio.watchlist.signal_prune_interval_seconds', 'exact', 'int', '300', 'Portfolio signal-watchlist prune: seconds between expiry prune ticks, read live each iteration. A stored value <=0 reads as 300, 1-59 as 60, above 86400 as 86400. Raising it is not a pause.', 'xstockstrat-portfolio', false, 'services/xstockstrat-portfolio/internal/service/signal_prune.go:pruneInterval', false),
