  ('trading', 'trading.approval.require_above_qty', 'exact', 'float', '500', 'Order qty threshold for approval', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:PlaceOrder', false),
  ('trading', 'trading.broker.paper', 'exact', 'bool', NULL, 'Route orders to the paper API when true, the live API when false; also the mode new broker accounts are registered in. The code default is environment-derived (TRADING_MODE == paper), so it has no single literal and must never be seeded from this catalog.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:environmentIsPaper; services/xstockstrat-trading/internal/service/trading.go:resolveTradingMode', false),
  ('trading', 'trading.broker.timeout_ms', 'exact', 'int', '5000', 'Alpaca broker HTTP call timeout. Read at account-client construction and applied as the broker HTTP client''s `Timeout`.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/order_intent.go:staleThreshold; services/xstockstrat-trading/internal/service/trading.go:brokerCallTimeout; services/xstockstrat-trading/internal/service/trading.go:instantiateBrokerLocked', false),
  ('trading', 'trading.credential_health.interval_ms', 'exact', 'int', '300000', 'Interval for the background poller that re-validates each broker account''s API secrets. Read live on every cycle; set to `0` (or negative) to disable/pause the poller without a restart.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:StartCredentialHealthPoller', false),
