  ('trading', 'trading.ibkr.handshake_timeout_ms', 'exact', 'int', '10000', 'Detached bound on one IBKR LST + `ssodh/init` handshake. Read live per handshake; `<= 0` reads as the default. Independent of `IBKRRequestTimeout`.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:ibkrTiming', false),
  ('trading', 'trading.ibkr.lst_refresh_margin_ms', 'exact', 'int', '60000', 'Refresh an IBKR account''s cached live session token (LST) this long before its `live_session_token_expiration`. Read live per handshake; `<= 0` reads as the default.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:ibkrTiming', false),
  ('trading', 'trading.ibkr.reauth_min_interval_ms', 'exact', 'int', '30000', 'IBKR negative-cache and 401-invalidation throttle: at most one LST request per interval per account with bad credentials. Read live per handshake; `<= 0` reads as the default.', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:ibkrTiming', false),
