  ('trading', 'trading.risk.bracket_orders_enabled', 'exact', 'bool', 'true', 'Master gate for automatic stop-loss/take-profit bracket orders on auto-sized entries — FALSE pending feature 103 or a documented manual verification', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:submitOrder; services/xstockstrat-trading/internal/service/trading.go:applyBrokerOrderStatus', false),
