  ('trading', 'trading.risk.max_position_pct', 'exact', 'float', '0.05', 'Max single position % of portfolio', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:PlaceOrder; services/xstockstrat-trading/internal/service/trading.go:checkPortfolioRisk', false),
  ('trading', 'trading.risk.max_risk_per_trade_pct', 'exact', 'float', '0.02', 'Fraction of equity to risk per trade (auto-sized orders only)', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:ComputePositionSize', false),
  ('trading', 'trading.risk.max_unprotected_seconds', 'exact', 'int', '30', 'Provisional default — max seconds an auto-sized position may remain without a confirmed bracket before automatic flatten+halt', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:maybeSubmitBracket', false),
  ('trading', 'trading.risk.sizing_enabled', 'exact', 'bool', 'true', 'Master gate for automatic position sizing; false rejects orders submitted without an explicit qty', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:PlaceOrder', false),
  ('trading', 'trading.risk.take_profit_rr_multiple', 'exact', 'float', '2', 'Reward-to-risk multiple for the take-profit leg; 0 disables the take-profit leg', 'xstockstrat-trading', false, 'services/xstockstrat-trading/internal/service/trading.go:computeTakeProfitPrice', false),
  ('ui', 'performance.equity_curve_start_date', 'exact', 'string', NULL, 'ISO date the cumulative-P&L equity curve starts from (feature 031, FR-1). Empty = auto: the UI defaults to the earliest closed-position date. Read one-shot via GetConfig; the UI treats '''' as absent.', 'xstockstrat-ui', false, 'services/xstockstrat-ui/src/lib/performanceMetrics.ts:readStartDateMs', false),
  ('ui', 'performance.risk_free_rate_annual', 'exact', 'float', '0.045', 'Annualized risk-free rate for the /insights performance dashboard rolling-30d Sharpe (feature 031, FR-3). Read one-shot via GetConfig with an oneof-presence check; a stored 0 is legitimate. Default 0.045.', 'xstockstrat-ui', false, 'services/xstockstrat-ui/src/lib/performanceMetrics.ts:readRiskFreeRate', false)
) AS catalog_041(namespace, key, match, value_type, code_default, description, consuming_service, is_secret, reader, readers_disagree)
-- catalog_041:end
  ;

  CREATE TEMP TABLE allow_041 ON COMMIT DROP AS
  SELECT * FROM
-- allow_041:begin
(VALUES
  ('analysis', 'backtest.max_duration_seconds', 'production', '2abaca4911e68fa9bfbf3482ee797fd5b9045b841fdff7253557c5fe15de6477'),
  ('analysis', 'backtest.max_duration_seconds', 'staging', '983bd614bb5afece5ab3b6023f71147cd7b6bc2314f9d27af7422541c6558389'),
  ('analysis', 'fundsignal.buy_quantile', 'production', '1d464f4ecc27b72a9ec9055c27fd9fb9266bee266546149204cc8732b0cffe39'),
  ('analysis', 'fundsignal.buy_quantile', 'staging', '1d464f4ecc27b72a9ec9055c27fd9fb9266bee266546149204cc8732b0cffe39'),
  ('analysis', 'fundsignal.daily_call_budget', 'production', '27badc983df1780b60c2b3fa9d3a19a00e46aac798451f0febdca52920faaddf'),
  ('analysis', 'fundsignal.daily_call_budget', 'staging', '27badc983df1780b60c2b3fa9d3a19a00e46aac798451f0febdca52920faaddf'),
  ('analysis', 'fundsignal.enabled', 'production', 'fcbcf165908dd18a9e49f7ff27810176db8e9f63b4352213741664245224f8aa'),
  ('analysis', 'fundsignal.enabled', 'staging', 'fcbcf165908dd18a9e49f7ff27810176db8e9f63b4352213741664245224f8aa'),
  ('analysis', 'fundsignal.explicit_symbols', 'production', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'),
  ('analysis', 'fundsignal.explicit_symbols', 'staging', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'),
  ('analysis', 'fundsignal.max_symbols_per_run', 'production', '27badc983df1780b60c2b3fa9d3a19a00e46aac798451f0febdca52920faaddf'),
  ('analysis', 'fundsignal.max_symbols_per_run', 'staging', '27badc983df1780b60c2b3fa9d3a19a00e46aac798451f0febdca52920faaddf'),
  ('analysis', 'fundsignal.min_conviction_to_emit', 'production', '8aed642bf5118b9d3c859bd4be35ecac75b6e873cce34e7b6f554b06f75550d7'),
  ('analysis', 'fundsignal.min_conviction_to_emit', 'staging', '8aed642bf5118b9d3c859bd4be35ecac75b6e873cce34e7b6f554b06f75550d7'),
  ('analysis', 'fundsignal.run_interval_hours', 'production', 'c2356069e9d1e79ca924378153cfbbfb4d4416b1f99d41a2940bfdb66c5319db'),
  ('analysis', 'fundsignal.run_interval_hours', 'staging', 'c2356069e9d1e79ca924378153cfbbfb4d4416b1f99d41a2940bfdb66c5319db'),
  ('analysis', 'fundsignal.scoring_formula_id', 'production', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'),
  ('analysis', 'fundsignal.scoring_formula_id', 'staging', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'),
  ('analysis', 'fundsignal.sell_quantile', 'production', '0e1a3f9422355b9afe6d53b976c5dc9c638e6a66d70cf2320d02c14761197e92'),
  ('analysis', 'fundsignal.sell_quantile', 'staging', '0e1a3f9422355b9afe6d53b976c5dc9c638e6a66d70cf2320d02c14761197e92'),
  ('analysis', 'fundsignal.source_slug', 'production', '64a3f18ab4fab2995094bbfe949a1a0c7bed763ace71ddc8f96227e16d11ac8c'),
  ('analysis', 'fundsignal.source_slug', 'staging', '64a3f18ab4fab2995094bbfe949a1a0c7bed763ace71ddc8f96227e16d11ac8c'),
  ('analysis', 'fundsignal.universe_source', 'production', '648809979605ed9c84b5307bfe83ace4cef0d2b706e40189cdfaf48a0be4fe71'),
  ('analysis', 'fundsignal.universe_source', 'staging', '648809979605ed9c84b5307bfe83ace4cef0d2b706e40189cdfaf48a0be4fe71'),
  ('analysis', 'fundsignal.valid_days', 'production', '69f59c273b6e669ac32a6dd5e1b2cb63333d8b004f9696447aee2d422ce63763'),
  ('analysis', 'fundsignal.valid_days', 'staging', '69f59c273b6e669ac32a6dd5e1b2cb63333d8b004f9696447aee2d422ce63763'),
  ('analysis', 'scoring.signal_decay_half_life_hours', 'production', 'dce81cca484053ef71096b308cb234b77b4ff19b507b7e033677c6a3827eaeef'),
  ('analysis', 'scoring.signal_decay_half_life_hours', 'staging', 'dce81cca484053ef71096b308cb234b77b4ff19b507b7e033677c6a3827eaeef'),
  ('ingest', 'backfill.chunk_max_bars', 'production', 'b552e632666bbf6125e3109e28a4fecc08340d017e44109dadbf497a280b8f82'),
  ('ingest', 'backfill.chunk_max_bars', 'staging', 'b552e632666bbf6125e3109e28a4fecc08340d017e44109dadbf497a280b8f82'),
  ('ingest', 'backfill.chunk_window_days', 'production', '69f59c273b6e669ac32a6dd5e1b2cb63333d8b004f9696447aee2d422ce63763'),
  ('ingest', 'backfill.chunk_window_days', 'staging', '69f59c273b6e669ac32a6dd5e1b2cb63333d8b004f9696447aee2d422ce63763'),
  ('ingest', 'backfill.max_concurrent_chunks', 'production', '4e07408562bedb8b60ce05c1decfe3ad16b72230967de01f640b7e4729b49fce'),
  ('ingest', 'backfill.max_concurrent_chunks', 'staging', '4e07408562bedb8b60ce05c1decfe3ad16b72230967de01f640b7e4729b49fce'),
  ('ingest', 'mcp_client.poll_interval_seconds', 'production', '983bd614bb5afece5ab3b6023f71147cd7b6bc2314f9d27af7422541c6558389'),
  ('ingest', 'mcp_client.poll_interval_seconds', 'staging', '983bd614bb5afece5ab3b6023f71147cd7b6bc2314f9d27af7422541c6558389'),
  ('ingest', 'mcp_client.request_timeout_seconds', 'production', '624b60c58c9d8bfb6ff1886c2fd605d2adeb6ea4da576068201b6c6958ce93f4'),
  ('ingest', 'mcp_client.request_timeout_seconds', 'staging', '624b60c58c9d8bfb6ff1886c2fd605d2adeb6ea4da576068201b6c6958ce93f4')
) AS allow_041(namespace, key, environment, value_sha256)
-- allow_041:end
  ;

  CREATE TEMP TABLE rep_041 (
    action text, namespace text, key text, environment text, user_id text,
    stored_value text, effective_value text, reason text, redact boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;
  CREATE TEMP TABLE touched_041 (namespace text, environment text) ON COMMIT DROP;

  -- Classify every pre-heal row; secret-class covers the row, its partner and either catalog spelling (S-1).
  CREATE TEMP TABLE cls_041 ON COMMIT DROP AS
  SELECT v.id, v.namespace, v.key, v.environment, v.user_id, v.is_secret, p.partner,
         EXISTS (SELECT 1 FROM catalog_041 c
                  WHERE c.namespace = v.namespace
                    AND ((c.match = 'exact' AND c.key = v.key)
                      OR (c.match = 'prefix' AND left(v.key, length(c.key)) = c.key))) AS in_cat,
         EXISTS (SELECT 1 FROM catalog_041 c
                  WHERE c.namespace = v.namespace AND c.match = 'exact' AND c.key = p.partner) AS partner_in_cat,
         (v.is_secret
          OR EXISTS (SELECT 1 FROM config.config_values t
                      WHERE t.namespace = v.namespace AND t.key = p.partner AND t.environment = v.environment
                        AND COALESCE(t.user_id, '') = COALESCE(v.user_id, '') AND t.is_secret)
          OR EXISTS (SELECT 1 FROM catalog_041 c
                      WHERE c.namespace = v.namespace AND c.is_secret
                        AND ((c.match = 'exact' AND c.key IN (v.key, p.partner))
                          OR (c.match = 'prefix' AND (left(v.key, length(c.key)) = c.key
                                                      OR left(p.partner, length(c.key)) = c.key))))) AS secret_class
  FROM config.config_values v
  CROSS JOIN LATERAL (
    SELECT CASE WHEN left(v.key, length(v.namespace) + 1) = v.namespace || '.'
                THEN substr(v.key, length(v.namespace) + 2)
                ELSE v.namespace || '.' || v.key END AS partner
  ) p;

  -- Snapshot: each distinct row state once, so a replay keeps the first pre-state.
  INSERT INTO config.config_values_premigration_041
  SELECT v.id, v.namespace, v.key, v.value_type,
         CASE WHEN k.secret_class THEN NULL ELSE v.value_data END,
         v.is_secret, v.description,
         CASE WHEN k.secret_class THEN NULL ELSE v.default_value END,
         v.consuming_service, v.updated_by, v.update_reason, v.created_at, v.updated_at, v.environment,
         v.caller_identity, v.user_id
  FROM config.config_values v
  JOIN cls_041 k ON k.id = v.id
  WHERE NOT EXISTS (SELECT 1 FROM config.config_values_premigration_041 s
                     WHERE s.id = v.id AND s.updated_at = v.updated_at);

  -- Readers-disagree keys come from the catalog flag; they are reported, never seeded or synced.
  INSERT INTO rep_041 (action, namespace, key, environment, stored_value, reason)
  SELECT 'readers-disagree', c.namespace, c.key, e.env,
         (SELECT v.value_data FROM config.config_values v
           JOIN cls_041 k ON k.id = v.id AND NOT k.secret_class
          WHERE v.namespace = c.namespace AND v.key = c.key AND v.environment = e.env AND v.user_id IS NULL),
         'readers disagree on default'
  FROM catalog_041 c
  CROSS JOIN (VALUES ('staging'), ('production')) AS e(env)
  WHERE c.readers_disagree;

  INSERT INTO rep_041 (action, namespace, key, environment, reason, redact)
  SELECT 'secret-read-unseeded', c.namespace, c.key, e.env, 'secret catalog key has no global row', true
  FROM catalog_041 c
  CROSS JOIN (VALUES ('staging'), ('production')) AS e(env)
  WHERE c.is_secret AND c.match = 'exact'
    AND NOT EXISTS (SELECT 1 FROM config.config_values v
                     WHERE v.namespace = c.namespace AND v.key = c.key AND v.environment = e.env
                       AND v.user_id IS NULL);

  -- Seed: an empty code default is unseedable for a non-string key (trading.broker.paper).
  WITH ins AS (
    INSERT INTO config.config_values
      (namespace, key, value_type, value_data, description, default_value, consuming_service, environment,
       user_id, updated_by, update_reason)
    SELECT c.namespace, c.key, c.value_type, COALESCE(c.code_default, ''), c.description,
           COALESCE(c.code_default, ''), c.consuming_service, e.env, NULL, v_by,
           'feature 295: seed reader catalog key'
    FROM catalog_041 c
    CROSS JOIN (VALUES ('staging'), ('production')) AS e(env)
    WHERE c.match = 'exact' AND NOT c.is_secret AND NOT c.readers_disagree
      AND (c.code_default IS NOT NULL OR c.value_type = 'string')
    ON CONFLICT (namespace, key, environment, COALESCE(user_id, '')) DO NOTHING
    RETURNING namespace, environment
  )
  INSERT INTO touched_041 SELECT namespace, environment FROM ins;

  -- Twin candidates: global, non-secret-class, unread rows whose other spelling is an exact catalog key.
  CREATE TEMP TABLE twin_041 ON COMMIT DROP AS
  SELECT k.id, k.namespace, k.key, k.environment, k.partner, b.value_data AS stored,
         t.value_data AS effective, t.id AS partner_id,
         (t.id IS NOT NULL AND EXISTS (
            SELECT 1 FROM allow_041 a
             WHERE a.namespace = k.namespace AND a.key = k.key AND a.environment = k.environment
               AND a.value_sha256 = encode(sha256(convert_to(b.value_data, 'UTF8')), 'hex'))) AS signed
  FROM cls_041 k
  JOIN config.config_values b ON b.id = k.id
  LEFT JOIN config.config_values t
    ON t.namespace = k.namespace AND t.key = k.partner AND t.environment = k.environment AND t.user_id IS NULL
  WHERE NOT k.in_cat AND k.partner_in_cat AND NOT k.secret_class AND k.user_id IS NULL;

  WITH d AS (
    DELETE FROM config.config_values v
    USING twin_041 w
    WHERE v.id = w.id AND w.signed
    RETURNING v.id, v.namespace, v.key, v.environment, v.user_id, v.value_data
  ), a AS (
    INSERT INTO config.config_audit
      (namespace, key, old_value, new_value, changed_by, reason, environment, user_id, caller_identity)
    SELECT namespace, key, value_data, NULL, v_by, 'feature 295: delete signed unread twin', environment,
           user_id, NULL
    FROM d
  ), r AS (
    INSERT INTO rep_041 (action, namespace, key, environment, stored_value, effective_value, reason)
    SELECT 'twin-deleted', w.namespace, w.key, w.environment, w.stored, w.effective,
           'signed unread twin of ' || w.partner
    FROM d JOIN twin_041 w ON w.id = d.id
  )
  INSERT INTO touched_041 SELECT namespace, environment FROM d;

  INSERT INTO rep_041 (action, namespace, key, environment, stored_value, effective_value, reason)
  SELECT 'twin-kept-unsigned', w.namespace, w.key, w.environment, w.stored, w.effective,
         CASE WHEN w.partner_id IS NULL THEN 'no global ' || w.partner || ' row to keep'
              ELSE 'tuple not in allow_041; twin of ' || w.partner END
  FROM twin_041 w
  WHERE NOT w.signed;

  -- Every other unread row is reported and kept; feature 296 deletes the dead ones (M-8).
  INSERT INTO rep_041 (action, namespace, key, environment, user_id, stored_value, reason, redact)
  SELECT CASE WHEN k.is_secret THEN 'secret-unread'
              WHEN k.secret_class THEN 'twin-secret-class'
              WHEN k.user_id IS NOT NULL THEN 'per-user-unread'
              ELSE 'unread-no-partner' END,
         k.namespace, k.key, k.environment, k.user_id, v.value_data,
         CASE WHEN k.is_secret THEN 'secret row matches no catalog key'
              WHEN k.secret_class THEN 'secret-class twin of ' || k.partner
              WHEN k.user_id IS NOT NULL THEN 'per-user row matches no catalog key'
              ELSE 'no reader and no catalog-spelled partner' END,
         k.secret_class OR k.user_id IS NOT NULL
  FROM cls_041 k
  JOIN config.config_values v ON v.id = k.id
  WHERE NOT k.in_cat
    AND NOT EXISTS (SELECT 1 FROM twin_041 w WHERE w.id = k.id);

  -- Retype only where the stored text already equals the code default; int rows under a float reader are valid.
  CREATE TEMP TABLE type_041 ON COMMIT DROP AS
  SELECT v.id, v.namespace, v.key, v.environment, v.user_id, v.value_data, v.value_type AS old_type,
         c.value_type AS new_type, c.code_default, c.readers_disagree,
         COALESCE(CASE c.value_type
                    WHEN 'int'    THEN v.value_data ~ '^-?(0|[1-9][0-9]*)$' AND v.value_data = c.code_default
                    WHEN 'float'  THEN v.value_data = c.code_default
                    WHEN 'bool'   THEN v.value_data IN ('true', 'false') AND v.value_data = c.code_default
                    WHEN 'string' THEN v.value_data = COALESCE(c.code_default, '')
                    ELSE false
                  END, false) AS eligible
  FROM config.config_values v
  JOIN catalog_041 c ON c.namespace = v.namespace AND c.match = 'exact' AND c.key = v.key
  WHERE NOT v.is_secret AND NOT c.is_secret
    AND NOT EXISTS (SELECT 1 FROM cls_041 k WHERE k.id = v.id AND k.secret_class)
    AND v.value_type <> c.value_type
    AND NOT (v.value_type = 'int' AND c.value_type = 'float');

  WITH u AS (
    UPDATE config.config_values v
    SET value_type = t.new_type, updated_by = v_by,
        update_reason = 'feature 295: retype to the reader value_type', caller_identity = NULL
    FROM type_041 t
    WHERE v.id = t.id AND t.eligible
    RETURNING v.namespace, v.key, v.environment, v.user_id, v.value_data
  ), a AS (
    INSERT INTO config.config_audit
      (namespace, key, old_value, new_value, changed_by, reason, environment, user_id, caller_identity)
    SELECT u.namespace, u.key, u.value_data, u.value_data, v_by,
           'feature 295: retype ' || t.old_type || ' -> ' || t.new_type, u.environment, u.user_id, NULL
    FROM u JOIN type_041 t ON t.namespace = u.namespace AND t.key = u.key AND t.environment = u.environment
                          AND COALESCE(t.user_id, '') = COALESCE(u.user_id, '')
  )
  INSERT INTO touched_041 SELECT namespace, environment FROM u;

  INSERT INTO rep_041 (action, namespace, key, environment, user_id, stored_value, effective_value, reason)
  SELECT CASE WHEN t.eligible THEN 'retyped' ELSE 'signoff-type' END,
         t.namespace, t.key, t.environment, t.user_id, t.value_data,
         CASE WHEN t.eligible THEN t.value_data WHEN NOT t.readers_disagree THEN t.code_default END,
         'stored ' || t.old_type || ', reader ' || t.new_type
  FROM type_041 t;

  -- Metadata fill: only NULL or empty fields, never on secret or secret-class rows.
  WITH u AS (
    UPDATE config.config_values v
    SET description = CASE WHEN COALESCE(v.description, '') = '' THEN c.description ELSE v.description END,
        consuming_service = CASE WHEN COALESCE(v.consuming_service, '') = '' THEN c.consuming_service
                                 ELSE v.consuming_service END,
        updated_by = v_by, update_reason = 'feature 295: fill reader-catalog metadata', caller_identity = NULL
    FROM catalog_041 c
    WHERE c.namespace = v.namespace AND c.match = 'exact' AND c.key = v.key
      AND NOT v.is_secret AND NOT c.is_secret
      AND NOT EXISTS (SELECT 1 FROM cls_041 k WHERE k.id = v.id AND k.secret_class)
      AND ((COALESCE(v.description, '') = '' AND c.description IS DISTINCT FROM v.description)
        OR (COALESCE(v.consuming_service, '') = '' AND c.consuming_service IS DISTINCT FROM v.consuming_service))
    RETURNING v.namespace, v.environment
  )
  INSERT INTO touched_041 SELECT namespace, environment FROM u;

  -- default_value is documentation (CONFIG-2): synced to the agreed code default, served value untouched.
  CREATE TEMP TABLE dsync_041 ON COMMIT DROP AS
  SELECT v.id, v.namespace, v.key, v.environment, v.user_id, v.value_data, v.default_value AS old_default,
         COALESCE(c.code_default, '') AS new_default
  FROM config.config_values v
  JOIN catalog_041 c ON c.namespace = v.namespace AND c.match = 'exact' AND c.key = v.key
  WHERE NOT v.is_secret AND NOT c.is_secret AND NOT c.readers_disagree
    AND (c.code_default IS NOT NULL OR c.value_type = 'string')
    AND NOT EXISTS (SELECT 1 FROM cls_041 k WHERE k.id = v.id AND k.secret_class)
    AND (CASE WHEN c.value_type IN ('int', 'float') AND v.default_value ~ v_num AND c.code_default ~ v_num
              THEN v.default_value::numeric = c.code_default::numeric
              WHEN c.value_type = 'bool' THEN lower(v.default_value) = lower(c.code_default)
              ELSE v.default_value = COALESCE(c.code_default, '')
         END) IS NOT TRUE;

  WITH u AS (
    UPDATE config.config_values v
    SET default_value = s.new_default, updated_by = v_by,
        update_reason = 'metadata: feature 295 default_value synced to the reader code default',
        caller_identity = NULL
    FROM dsync_041 s
    WHERE v.id = s.id
    RETURNING v.namespace, v.environment
  ), a AS (
    INSERT INTO config.config_audit
      (namespace, key, old_value, new_value, changed_by, reason, environment, user_id, caller_identity)
    SELECT s.namespace, s.key, s.old_default, s.new_default, v_by,
           'metadata: default_value synced to the reader code default', s.environment, s.user_id, NULL
    FROM dsync_041 s
  )
  INSERT INTO touched_041 SELECT namespace, environment FROM u;

  INSERT INTO rep_041 (action, namespace, key, environment, user_id, stored_value, effective_value, reason)
  SELECT 'default-synced', s.namespace, s.key, s.environment, s.user_id, s.value_data, s.value_data,
         'default_value ' || COALESCE(s.old_default, 'NULL') || ' -> ' || s.new_default || '; value_data unchanged'
  FROM dsync_041 s;

  -- Out-of-bounds report for the bounds this feature adds to the config service.
  INSERT INTO rep_041 (action, namespace, key, environment, user_id, stored_value, reason)
  SELECT 'out-of-bounds', v.namespace, v.key, v.environment, v.user_id, v.value_data,
         'outside [' || b.lo || ', ' || b.hi || ']'
  FROM config.config_values v
  JOIN (VALUES ('indicators', 'indicators.sandbox.startup_grace_ms', 1000, 10000),
               ('indicators', 'indicators.sandbox.timeout_ms', 100, 33000),
               ('analysis', 'analysis.compute.max_worker_threads', 1, 16)) AS b(namespace, key, lo, hi)
    ON b.namespace = v.namespace AND b.key = v.key
  WHERE NOT v.is_secret
    AND (CASE WHEN v.value_data ~ v_num THEN v.value_data::numeric END) NOT BETWEEN b.lo AND b.hi;

  INSERT INTO config.config_heal_report_041
    (run_at, action, namespace, key, environment, user_id, stored_value, effective_value, reason)
  SELECT v_run, action, namespace, key, environment, user_id,
         CASE WHEN redact OR user_id IS NOT NULL THEN NULL ELSE stored_value END,
         CASE WHEN redact OR user_id IS NOT NULL THEN NULL ELSE effective_value END,
         reason
  FROM rep_041;

  PERFORM pg_notify('config_changed', json_build_object('namespace', t.namespace, 'environment', t.environment)::text)
  FROM (SELECT DISTINCT namespace, environment FROM touched_041) t;

  INSERT INTO config.config_heal_report_041 (run_at, action, reason)
  VALUES (v_run, 'latch', 'feature 295 heal applied; delete this row to re-run 041');
END $$;
